import urllib.request, ssl, re, json; ctx = ssl.create_default_context(); ctx.check_hostname = False; ctx.verify_mode = ssl.CERT_NONE; req = urllib.request.Request('https://m.flashscore.com/match/67VRHb7k/?t=stats', headers={'User-Agent': 'Mozilla/5.0'}); html = urllib.request.urlopen(req, context=ctx).read().decode('utf-8'); env = re.search(r'window\.environment\s*=\s*(\{.*?\});', html, flags=re.DOTALL); feed = json.loads(env.group(1)).get('props', {}).get('feed', ''); print(feed)
